import{_ as a,o,c as t,a2 as r}from"./chunks/framework.DQhM5RF8.js";const u=JSON.parse('{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"info/faq.md","filePath":"info/faq.md"}'),n={name:"info/faq.md"};function i(s,e,l,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h1><h3 id="is-llamacraft-free-to-play" tabindex="-1">Is LlamaCraft free to play? <a class="header-anchor" href="#is-llamacraft-free-to-play" aria-label="Permalink to &quot;Is LlamaCraft free to play?&quot;">​</a></h3><p>Yes. LlamaCraft is completely free with no pay-to-win kits, paywalls, or paid ranks that grant unfair advantages.</p><hr><h3 id="what-minecraft-versions-are-supported" tabindex="-1">What Minecraft versions are supported? <a class="header-anchor" href="#what-minecraft-versions-are-supported" aria-label="Permalink to &quot;What Minecraft versions are supported?&quot;">​</a></h3><ul><li><strong>Java Edition</strong>: <code>1.20.1</code> through <code>1.21.x</code>.</li><li><strong>Bedrock Edition</strong>: Current release (<code>1.21.x</code>).</li><li><strong>Education Edition</strong>: Supported through protocol translation.</li></ul><hr><h3 id="do-i-need-a-modded-minecraft-launcher" tabindex="-1">Do I need a modded Minecraft launcher? <a class="header-anchor" href="#do-i-need-a-modded-minecraft-launcher" aria-label="Permalink to &quot;Do I need a modded Minecraft launcher?&quot;">​</a></h3><p>No. Vanilla clients can connect on both Java and Bedrock. Only players who want native keybound Simple Voice Chat on Java require the client mod; Bedrock and console players can connect to voice chat via the browser audio link or companion app.</p><hr><h3 id="can-xbox-and-playstation-players-hear-voice-chat" tabindex="-1">Can Xbox and PlayStation players hear voice chat? <a class="header-anchor" href="#can-xbox-and-playstation-players-hear-voice-chat" aria-label="Permalink to &quot;Can Xbox and PlayStation players hear voice chat?&quot;">​</a></h3><p>Yes. Console players open the voice chat link on their mobile phone or tablet browser while playing on their console. The audio engine links to your Xbox/PS Gamertag and outputs proximity directional audio through your mobile headset.</p><hr><h3 id="how-do-i-protect-my-house-and-chests" tabindex="-1">How do I protect my house and chests? <a class="header-anchor" href="#how-do-i-protect-my-house-and-chests" aria-label="Permalink to &quot;How do I protect my house and chests?&quot;">​</a></h3><p>Use a golden shovel or type <code>/claim</code> while holding it to set two opposite corners around your build. You can trust friends using <code>/trust &lt;player&gt;</code> or manage permissions with <code>/claimsettings</code>.</p>',15)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
